function getPRNumber(params, storyKey, scm) {
    let prNumber = null;
    let prUrl = null;
    let prBranch = null;

    try {
        const inputFolder = params.inputFolderPath || ('input/' + storyKey);
        const prInfo = readFile(inputFolder + '/pr_info.md');
